import{_ as a,C as n,o as s,c as o,j as t,a as i,E as h,ak as l}from"./chunks/framework.sV-XtlWr.js";const y=JSON.parse('{"title":"Timeline markers","description":"","frontmatter":{"title":"Timeline markers","lang":"en-US"},"headers":[],"relativePath":"features/timeline-markers.md","filePath":"features/timeline-markers.md","lastUpdated":1790422632000}'),d={name:"features/timeline-markers.md"};function c(p,e,m,u,g,k){const r=n("Needs");return s(),o("div",null,[e[0]||(e[0]=t("h1",{id:"timeline-markers",tabindex:"-1"},[i("Timeline markers "),t("a",{class:"header-anchor",href:"#timeline-markers","aria-label":'Permalink to "Timeline markers"'},"​")],-1)),h(r,{reporter:"",admin:""}),e[1]||(e[1]=l('<p>Timeline markers let you record <strong>dated events</strong> against a project — a deploy, a config change, an infrastructure migration, a dependency bump, an incident — and see them overlaid as vertical lines on the analytics trend charts. When a pass-rate drop or a performance regression lines up with a marker, you have your prime suspect: &quot;the slowdown started the day we switched CI runners&quot;.</p><h2 id="what-a-marker-is" tabindex="-1">What a marker is <a class="header-anchor" href="#what-a-marker-is" aria-label="Permalink to &quot;What a marker is&quot;">​</a></h2><p>Each marker belongs to one project and carries:</p><ul><li><strong>Label</strong> — a short title (e.g. <em>Migrated CI to ARM runners</em>).</li><li><strong>Date &amp; time</strong> — when the event happened; this is where the line is drawn.</li><li><strong>Category</strong> — one of <code>deploy</code>, <code>config</code>, <code>infra</code>, <code>incident</code>, <code>release</code>, or a generic <code>event</code>. The category sets the marker&#39;s icon and color.</li><li><strong>Environment</strong> <em>(optional)</em> — scope the marker to a single environment (e.g. <code>staging</code>). Leave it empty to apply to all environments.</li><li><strong>Description</strong> <em>(optional)</em> — free-text detail.</li><li><strong>Run</strong> <em>(optional, API only)</em> — the id of one of the project&#39;s runs the event belongs to.</li></ul><h2 id="where-markers-show-up" tabindex="-1">Where markers show up <a class="header-anchor" href="#where-markers-show-up" aria-label="Permalink to &quot;Where markers show up&quot;">​</a></h2><ul><li><strong>Project charts</strong> — the <strong>Run trend</strong> and <strong>Performance trend</strong> charts render each marker as a dashed vertical line with a colored flag handle. Hover the handle for the marker&#39;s details; click it to open the <strong>Markers</strong> panel focused on that marker.</li><li><strong>Markers panel</strong> — a <strong>Markers</strong> button beside the <strong>Run trend</strong> chart (on the project&#39;s Runs tab) opens a panel listing the project&#39;s markers, with add / edit / delete controls.</li><li><strong>Test-case history</strong> — a single test&#39;s duration history chart shows the same markers, so you can tell whether an event affected that specific test.</li><li><strong>Run detail</strong> — a run shows an <strong>&quot;After: …&quot;</strong> chip for the nearest preceding marker, so a single run tells you which event it followed.</li><li><strong>Run compare</strong> — comparing two runs surfaces any markers that fall between them (&quot;something changed between these runs&quot;).</li></ul><h2 id="environment-scoping" tabindex="-1">Environment scoping <a class="header-anchor" href="#environment-scoping" aria-label="Permalink to &quot;Environment scoping&quot;">​</a></h2><p>Markers tie into the project&#39;s existing <strong>environment filter</strong>. When you filter the project view to one or more environments, the charts show only markers that match the selected environment(s) plus any global (no-environment) markers. This keeps a staging-only event from cluttering your production view.</p><p>The environment field is free text, with suggestions drawn from the environments already seen in the project&#39;s runs (set via the reporter&#39;s <code>environment</code> option / <code>PIWI_ENVIRONMENT</code>).</p><h2 id="who-can-edit-markers" tabindex="-1">Who can edit markers <a class="header-anchor" href="#who-can-edit-markers" aria-label="Permalink to &quot;Who can edit markers&quot;">​</a></h2><p>Reading markers is available to any signed-in user with access to the project. Creating, editing, and deleting them requires the <strong>reporter</strong> or <strong>administrator</strong> role. (When authentication is disabled, everyone can edit.)</p><h2 id="automatic-markers" tabindex="-1">Automatic markers <a class="header-anchor" href="#automatic-markers" aria-label="Permalink to &quot;Automatic markers&quot;">​</a></h2><p>Piwi can create markers for you when a run&#39;s tooling changes. On each finished run it compares the run against the previous run <strong>in the same environment</strong> and, when the <strong>Playwright version</strong> or <strong>reporter version</strong> changed, adds an <code>auto</code> marker (category <code>config</code>) at that run&#39;s time — for example <em>Playwright 1.49.0 → 1.50.0</em>. Auto markers are labeled with a small sparkle icon and can be edited or deleted like any other.</p><p>This is enabled by default. Set <code>PIWI_AUTO_MARKERS=false</code> to turn it off. See the <a href="/reference/configuration.html">configuration reference</a>.</p><h2 id="release-markers-keep-their-run" tabindex="-1">Release markers keep their run <a class="header-anchor" href="#release-markers-keep-their-run" aria-label="Permalink to &quot;Release markers keep their run&quot;">​</a></h2><p>A <code>release</code> marker linked to a run keeps that run forever: <a href="/operate/storage.html#keeping-runs-forever">data retention</a> never deletes it, and the marker&#39;s label becomes the reason shown on the run. Deleting the marker, or changing its category to anything but <code>release</code>, releases the run again — unless someone kept it by hand or the reporter kept it at ingest, in which case the keep stays.</p><p>From CI, create the marker after the test step with the run id the reporter writes to its outputs (<code>piwi_run_id</code> on GitHub Actions, see <a href="/guide/ci.html#getting-the-run-url-back-out-of-ci">CI → Getting the run URL back out</a>):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PIWI_DASHBOARD_URL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/api/projects/&lt;projectId&gt;/markers&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PIWI_API_KEY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;label&quot;:&quot;v2.3.1&quot;,&quot;category&quot;:&quot;release&quot;,&quot;occurredAt&quot;:&quot;2026-09-24T12:00:00Z&quot;,&quot;runId&quot;:1234}&#39;</span></span></code></pre></div><h2 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h2><p>Markers are managed through the REST API (<code>GET</code>/<code>POST /api/projects/:id/markers</code>, <code>PATCH</code>/<code>DELETE /api/markers/:id</code>). See the interactive <a href="https://piwitests.dev/demo/docs" target="_blank" rel="noreferrer">API docs</a> for request and response shapes.</p>',20))])}const v=a(d,[["render",c]]);export{y as __pageData,v as default};
